def box(x,y,w,h,title,body,color='#e8f2ef'):
 ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=.01',fc=color,ec='#658c80'))
 ax.text(x+.02,y+h-.025,title,fontsize=13,weight='bold',va='top');ax.text(x+.02,y+h-.082,body,fontsize=11.5,va='top',linespacing=1.45)
def arrow(a,b):ax.annotate('',xy=b,xytext=a,arrowprops=dict(arrowstyle='->',lw=1.8,color='#365e50'))
ax.text(.04,.99,'Two paths from the same legal history',va='top',fontsize=18,weight='bold')
box(.04,.75,.92,.15,'Filter events BEFORE sampling or aggregation','Legal credits [10, 20, 30, 40] → N = 4, total $100\nFuture credit [1,000] is excluded at the cutoff')
box(.04,.45,.43,.20,'Sample two events','Retain [10, 20] → sum $30\nUnseen [30, 40] omitted\nOnly k = 2 records retained')
