def figure(name,alt,portable=False):
 src='data:image/png;base64,'+base64.b64encode((F/f'{name}.png').read_bytes()).decode() if portable else f'../labs/figures/b18/{name}.png'
 return f'<figure class="context-figure" tabindex="0" role="region" aria-label="{alt}"><img src="{src}" alt="{alt}"><figcaption>{alt}</figcaption></figure>'
pipe='''<section class="context-board" aria-label="Information pipeline"><h3>From events to an answer</h3><div class="context-flow"><div class="context-step"><strong>Raw events → cutoff and kind filter</strong>[10,20,30,40] are legal credits. Future credit [1,000] is excluded before any count or sum.</div><div class="context-branches"><div class="context-step"><strong>Sample path</strong>4 events → retain [10,20] → sum 30 → add full count N=4 → correct 30 × 4/2 = 60.</div><div class="context-step"><strong>Complete aggregate path</strong>4 events → scan 10 + 20 + 30 + 40 → one monthly record 100 → read exact historical total 100.</div></div><div class="context-step"><strong>What a downstream model can read</strong>Sampled rows omit arbitrary amounts. A full aggregate carries the sum, but loses ordering and extremes. No forecasting model is executed here.</div></div></section>'''
control='''<section class="context-board" data-context-budget><h3>Predict, then change the budget</h3><p>Held fixed: total $1,200, sampling rule, 100 repetitions and all four estimation methods. Values below are saved author measurements.</p><div class="context-controls">'''
for name,values,default in [('seed',[0,1,2],0),('degree',[8,64,512,4096],4096),('shape',['uniform','concentrated'],'concentrated'),('budget',[8,32,128,512],32)]:
 control+=f'<label>{name.capitalize()} <select name="{name}">'+''.join(f'<option value="{v}"'+(' selected' if v==default else '')+f'>{v}</option>' for v in values)+'</select></label>'
control+='''</div><output aria-live="polite">Author measurements are in the table below; enable JavaScript to explore all 96 states.</output><p data-interpret>Compare sampled and corrected RMSE, not only signed bias.</p><button type="button">Reset budget</button><noscript><p>The static table and plot below preserve the key results without JavaScript.</p></noscript></section>'''
results='**Author reference: degree 4,096, concentrated amounts, budget 32.** Each row summarizes 100 draws. Dollar amounts rounded to cents.\n\n| Seed | Sample bias | Sample RMSE | Corrected bias | Corrected RMSE | Aggregate RMSE |\n|---:|---:|---:|---:|---:|---:|\n'
for c in r['conditions']:
 if c['degree']==4096 and c['shape']=='concentrated' and c['budget']==32:
  m=c['metrics'];results+=f"| {c['seed']} | {m['sampled']['bias']:.2f} | {m['sampled']['rmse']:.2f} | {m['corrected']['bias']:.2f} | {m['corrected']['rmse']:.2f} | {m['aggregate']['rmse']:.2f} |\n"
texts={'WORKED':('six-pairs','Exact enumeration: correction averages to $100 but individual totals range from $60 to $140.'),'PIPELINE':('information-path','Course pipeline: time filtering precedes sampling or aggregation; full counts add information.'),'RESULT_FIG':('degree-errors','Measured reconstruction RMSE, three seeds, degree 4096. Concentration makes corrected totals variable.')}

def document(title,body,interactive=False):
 html=render(body).replace('<table>','<div class="context-table" tabindex="0" role="region" aria-label="Scrollable results table"><table>').replace('</table>','</table></div>')
 scripts=['retrieval-pool','retrieval-bank','predict','teachback','temporal-visibility','b18-evidence','context-budget'] if interactive else []
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link rel="stylesheet" href="../assets/lesson.css"><link rel="stylesheet" href="../assets/context-budget.css"><link rel="stylesheet" href="../assets/temporal-lesson.css"></head><body><article><nav><a href="../index.html">Course</a> · <a href="../notebooks.html">Notebook gallery</a></nav>'+html+'</article>'+''.join(f'<script src="../assets/{s}.js"></script>' for s in scripts)+'</body></html>'
body=(R/'lessons/content'/f'{S}.md').read_text();lesson=body
for key,(name,alt) in texts.items():lesson=lesson.replace('{{'+key+'}}',pipe if key=='PIPELINE' else figure(name,alt))
lesson=lesson.replace('{{CONTROL}}',control).replace('{{RESULTS}}',results)
(R/'lessons'/f'{S}.html').write_text(document('B18 · Context-window failure and sufficient evidence',lesson,True))
ref='''# B18 · Context sufficiency reference

[Lesson](../lessons/b18-context-sufficiency.html) · [Notebook](../labs/b18-context-sufficiency.ipynb) · [Reproduction contract](../labs/b18-reproduction.md)

| Question | Rule |
|---|---|
| Which events count? | Filter event and availability time by the query cutoff before counting or aggregating |
| What is degree? | Number of eligible related events; declare the event types and time window |
| What is truncated? | Raw sampled sum retains only the observed mass |
| When is N/k correction unbiased? | Uniform sampling without replacement, exact eligible N, k>0 |
| Does unbiased mean exact? | No; concentrate most value in one event to expose variance |
| What is preserved by monthly sums? | The historical sum query; not arbitrary ordering, extremes or future targets |
| What information does aggregation cost? | Access to the complete eligible history, possibly maintained incrementally |
| Which bins are legal inference inputs? | Bins defined from available history, never post-cutoff outcomes |

For fixed historical sum S, E[Sₖ]=(k/N)S. Therefore E[(N/k)Sₖ]=S. Four events [10,20,30,40], k=2: corrected totals [60,80,100,100,120,140], mean 100. For a finite population with variance σ²=mean((x−mean(x))²), Var(Ŝ)=N²(1−k/N)σ²/k × N/(N−1), for N>1. At k=N variance is zero; concentrated amounts increase it.

Bias=mean(prediction−target); RMSE=sqrt(mean((prediction−target)²)). Report both, by historical degree, with every seed. In B18: 24 histories, 96 conditions, 100 draws each, four arms. This is historical reconstruction, not a forecast or a trained-model benchmark.

**Paper audit:** Animus v1 RT main-table positive scores conflict with negative Appendix B entries; best-test captions require selection clarification;474 selected customers are not the complete 10,000-customer test population. [Primary paper](https://arxiv.org/html/2609.00460v1). Paper NOT_RUN / INCOMPLETE_SOURCE_PROTOCOL_GATE. No sign repair or substitute dataset.

**Next experiment:** freeze legal inputs, model selection and complete test population; vary context budget; save sampled IDs; stratify by predeclared historical degree; count the work required to supply N or aggregates. Do not infer broad industry prevalence from a synthetic counterexample.
'''
(R/'reference'/f'{S}.html').write_text(document('B18 · Context sufficiency reference',ref))
